let file = """{"version":3,"file":"ssoEntryQuery-581OTOYw.js","names":[],"sources":["../../packages/account-core/src/redirect.ts","../../packages/account-core/src/sso.ts","../../src/platform/cloud/onboarding/sso/ssoEntryQuery.ts"],"sourcesContent":["/** True if the string contains any C0 control char the URL parser would strip. */\nfunction hasControlChar(value: string): boolean {\n  for (let i = 0; i < value.length; i++) {\n    if (value.charCodeAt(i) <= 0x1f) return true\n  }\n  return false\n}\n\n/**\n * Where a visitor may be sent after sign-in. Only a same-origin absolute\n * path qualifies; anything that could leave the origin (a protocol-relative\n * or backslash prefix, an absolute or javascript: URL, or a path hiding one\n * of those behind a stripped control char) falls back.\n *\n * The prefix checks alone are not enough: the WHATWG URL parser strips C0\n * control chars (tab, LF, CR) before parsing, so `/<TAB>//evil.com` passes a\n * literal `startsWith('//')` check yet the browser resolves it cross-origin.\n * So a control char is rejected outright, and the result is re-parsed against\n * the origin to confirm it truly stays same-origin.\n */\nexport function safeInternalPath(\n  raw: string | null | undefined,\n  origin: string,\n  fallback: string\n): string {\n  if (\n    typeof raw !== 'string' ||\n    !raw.startsWith('/') ||\n    raw.startsWith('//') ||\n    raw.startsWith('/\\\\') ||\n    hasControlChar(raw)\n  ) {\n    return fallback\n  }\n  try {\n    const resolved = new URL(raw, origin)\n    if (resolved.origin !== origin) return fallback\n    return resolved.pathname + resolved.search + resolved.hash\n  } catch {\n    return fallback\n  }\n}\n","/**\n * Enterprise SSO sign-in through ingest: the discover call that tells whether\n * an email signs in through its organization, the start URL the browser\n * navigates to, and the codes a failed sign-in comes back with. Hosts own the\n * copy; nothing here is text a person reads.\n */\nimport type { SsoDiscoverResponse } from '@comfyorg/ingest-types'\nimport {\n  zDiscoverSsoBody,\n  zDiscoverSsoResponse,\n  zErrorResponse\n} from '@comfyorg/ingest-types/zod'\n\nimport { timedSignal } from './core/requestTimeout.js'\nimport { safeInternalPath } from './redirect.js'\n\nexport {\n  isAccountOutsideOrganizationRefusal,\n  isSsoRequiredRefusal,\n  ssoRequiredOrganizationId\n} from './core/ssoRequired.js'\n\nconst SSO_DISCOVER_PATH = '/api/auth/sso/discover'\nconst SSO_START_PATH = '/api/auth/sso/start'\nconst DEFAULT_DISCOVER_TIMEOUT_MS = 5000\n\nexport type SsoDiscovery =\n  | { readonly kind: 'sso'; readonly organizationName?: string }\n  | { readonly kind: 'not-sso' }\n  | { readonly kind: 'invalid-email' }\n  | { readonly kind: 'unavailable' }\n\nexport interface DiscoverSsoOptions {\n  readonly fetchImpl: typeof fetch\n  readonly signal?: AbortSignal\n  /** Ingest origin; empty (the default) means same-origin. */\n  readonly baseUrl?: string\n  /** A sign-in waits on this call, so it is bounded. Default 5s. */\n  readonly timeoutMs?: number\n}\n\nfunction fromResponse(body: SsoDiscoverResponse): SsoDiscovery {\n  if (!body.sso) return { kind: 'not-sso' }\n  return body.organization_name === undefined\n    ? { kind: 'sso' }\n    : { kind: 'sso', organizationName: body.organization_name }\n}\n\nasync function readJson(response: Response): Promise<unknown> {\n  try {\n    return await response.json()\n  } catch {\n    return undefined\n  }\n}\n\nfunction classify(status: number, body: unknown): SsoDiscovery {\n  if (status === 200) {\n    const parsed = zDiscoverSsoResponse.safeParse(body)\n    return parsed.success ? fromResponse(parsed.data) : { kind: 'unavailable' }\n  }\n  const error = zErrorResponse.safeParse(body)\n  return status === 400 && error.success && error.data.code === 'INVALID_EMAIL'\n    ? { kind: 'invalid-email' }\n    : { kind: 'unavailable' }\n}\n\n/**\n * Whether an email signs in through its organization's SSO. Never throws: a\n * network failure, timeout, unexpected status or unreadable body is\n * `unavailable`, so a caller can fall back to its usual sign-in.\n */\nexport async function discoverSso(\n  email: string,\n  options: DiscoverSsoOptions\n): Promise<SsoDiscovery> {\n  const request = zDiscoverSsoBody.safeParse({ email: email.trim() })\n  if (!request.success || request.data.email === '') {\n    return { kind: 'invalid-email' }\n  }\n  const { signal, release } = timedSignal(\n    options.signal,\n    options.timeoutMs ?? DEFAULT_DISCOVER_TIMEOUT_MS\n  )\n  try {\n    const response = await options.fetchImpl(\n      `${options.baseUrl ?? ''}${SSO_DISCOVER_PATH}`,\n      {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify(request.data),\n        signal\n      }\n    )\n    return classify(response.status, await readJson(response))\n  } catch {\n    return { kind: 'unavailable' }\n  } finally {\n    release()\n  }\n}\n\n/**\n * Ingest sends API routes back to `/`: they refuse a cross-site navigation,\n * so the person would land on an error. Anything off-origin goes there too.\n */\nfunction isApiRoute(url: URL): boolean {\n  const pathname = url.pathname.toLowerCase()\n  return pathname === '/api' || pathname.startsWith('/api/')\n}\n\nfunction ssoReturnTo(\n  raw: string,\n  origin: string,\n  appOrigin: string | undefined\n): string {\n  if (appOrigin !== undefined && URL.canParse(raw)) {\n    const url = new URL(raw)\n    if (url.origin === appOrigin) return isApiRoute(url) ? '/' : url.href\n  }\n  const path = safeInternalPath(raw, origin, '/')\n  return isApiRoute(new URL(path, origin)) ? '/' : path\n}\n\n/** A named organization is the target; otherwise the email's domain is. */\ntype SsoStartTarget =\n  | { readonly email: string; readonly organizationId?: string }\n  | { readonly email?: string; readonly organizationId: string }\n\n/**\n * Where the browser goes to sign in with SSO. Ingest answers with a redirect\n * to the identity provider, so this is for a full-page navigation, never a\n * fetch.\n */\nexport function ssoStartUrl(\n  options: SsoStartTarget & {\n    readonly returnTo: string\n    readonly origin: string\n    /**\n     * The calling app's own origin when it is not Cloud's (billing-web,\n     * platform): a `returnTo` on it is sent whole, and ingest returns there\n     * only when the origin is an https one it trusts with the web session.\n     */\n    readonly appOrigin?: string\n  }\n): string {\n  const url = new URL(SSO_START_PATH, options.origin)\n  if (options.email !== undefined) {\n    url.searchParams.set('email', options.email.trim())\n  }\n  if (options.organizationId !== undefined) {\n    url.searchParams.set('organization', options.organizationId)\n  }\n  url.searchParams.set(\n    'return_to',\n    ssoReturnTo(options.returnTo, options.origin, options.appOrigin)\n  )\n  return url.toString()\n}\n\n/** Every code ingest's SSO start and callback send back as `?sso_error=`. */\nconst SSO_ERROR_CODES = [\n  'INTERNAL_ERROR',\n  'RATE_LIMITED',\n  'SESSION_CREATION_FAILED',\n  'SSO_ACCOUNT_CONFLICT',\n  'SSO_ACCOUNT_DELETED',\n  'SSO_CONFIRM_EXPIRED',\n  'SSO_EMAIL_DOMAIN_NOT_ALLOWED',\n  'SSO_EXCHANGE_FAILED',\n  'SSO_IDP_ERROR',\n  'SSO_INVALID_STATE',\n  'SSO_LINK_CHECK_FAILED',\n  'SSO_NOT_CONFIGURED',\n  'SSO_ORG_DISABLED',\n  'SSO_ORG_MISMATCH',\n  'SSO_ORG_NOT_ATTACHED',\n  'SSO_SIGN_IN_FAILED',\n  'SSO_UNAVAILABLE',\n  'SSO_USER_SUSPENDED'\n] as const\n\nexport type SsoErrorCode = (typeof SSO_ERROR_CODES)[number]\n\nconst KNOWN_SSO_ERRORS: ReadonlySet<string> = new Set(SSO_ERROR_CODES)\n\nfunction isSsoErrorCode(value: string): value is SsoErrorCode {\n  return KNOWN_SSO_ERRORS.has(value)\n}\n\n/**\n * Reads an `?sso_error=` query value. Absent is undefined; a code this build\n * predates reads as a generic sign-in failure, so it still gets a message.\n */\nexport function readSsoError(value: unknown): SsoErrorCode | undefined {\n  const raw = Array.isArray(value) ? value[0] : value\n  if (typeof raw !== 'string' || raw === '') return undefined\n  return isSsoErrorCode(raw) ? raw : 'SSO_SIGN_IN_FAILED'\n}\n","/** The login page query that opens it on its SSO entry. */\nexport const SSO_ENTRY_OPEN_QUERY = { sso: 'open' } as const\n"],"mappings":"qIACA,SAAS,eAAe,EAAwB,CAC9C,IAAK,IAAI,EAAI,EAAG,EAAI,EAAM,OAAQ,IAChC,GAAI,EAAM,WAAW,CAAC,GAAK,GAAM,MAAO,GAE1C,MAAO,EACT,CAcA,SAAgB,iBACd,EACA,EACA,EACQ,CACR,GACE,OAAO,GAAQ,UACf,CAAC,EAAI,WAAW,GAAG,GACnB,EAAI,WAAW,IAAI,GACnB,EAAI,WAAW,KAAK,GACpB,eAAe,CAAG,EAElB,OAAO,EAET,GAAI,CACF,IAAM,EAAW,IAAI,IAAI,EAAK,CAAM,EAEpC,OADI,EAAS,SAAW,EACjB,EAAS,SAAW,EAAS,OAAS,EAAS,KADf,CAEzC,MAAQ,CACN,OAAO,CACT,CACF,CCnBA,IAAM,EAAoB,yBACpB,EAAiB,sBACjB,EAA8B,IAiBpC,SAAS,aAAa,EAAyC,CAE7D,OADK,EAAK,IACH,EAAK,oBAAsB,IAAA,GAC9B,CAAE,KAAM,KAAM,EACd,CAAE,KAAM,MAAO,iBAAkB,EAAK,iBAAkB,EAHtC,CAAE,KAAM,SAAU,CAI1C,CAEA,eAAe,SAAS,EAAsC,CAC5D,GAAI,CACF,OAAO,MAAM,EAAS,KAAK,CAC7B,MAAQ,CACN,MACF,CACF,CAEA,SAAS,SAAS,EAAgB,EAA6B,CAC7D,GAAI,IAAW,IAAK,CAClB,IAAM,EAAS,EAAqB,UAAU,CAAI,EAClD,OAAO,EAAO,QAAU,aAAa,EAAO,IAAI,EAAI,CAAE,KAAM,aAAc,CAC5E,CACA,IAAM,EAAQ,EAAe,UAAU,CAAI,EAC3C,OAAO,IAAW,KAAO,EAAM,SAAW,EAAM,KAAK,OAAS,gBAC1D,CAAE,KAAM,eAAgB,EACxB,CAAE,KAAM,aAAc,CAC5B,CAOA,eAAsB,YACpB,EACA,EACuB,CACvB,IAAM,EAAU,EAAiB,UAAU,CAAE,MAAO,EAAM,KAAK,CAAE,CAAC,EAClE,GAAI,CAAC,EAAQ,SAAW,EAAQ,KAAK,QAAU,GAC7C,MAAO,CAAE,KAAM,eAAgB,EAEjC,GAAM,CAAE,SAAQ,WAAY,EAC1B,EAAQ,OACR,EAAQ,WAAa,CACvB,EACA,GAAI,CACF,IAAM,EAAW,MAAM,EAAQ,UAC7B,GAAG,EAAQ,SAAW,KAAK,IAC3B,CACE,OAAQ,OACR,QAAS,CAAE,eAAgB,kBAAmB,EAC9C,KAAM,KAAK,UAAU,EAAQ,IAAI,EACjC,QACF,CACF,EACA,OAAO,SAAS,EAAS,OAAQ,MAAM,SAAS,CAAQ,CAAC,CAC3D,MAAQ,CACN,MAAO,CAAE,KAAM,aAAc,CAC/B,QAAU,CACR,EAAQ,CACV,CACF,CAMA,SAAS,WAAW,EAAmB,CACrC,IAAM,EAAW,EAAI,SAAS,YAAY,EAC1C,OAAO,IAAa,QAAU,EAAS,WAAW,OAAO,CAC3D,CAEA,SAAS,YACP,EACA,EACA,EACQ,CACR,GAAI,IAAc,IAAA,IAAa,IAAI,SAAS,CAAG,EAAG,CAChD,IAAM,EAAM,IAAI,IAAI,CAAG,EACvB,GAAI,EAAI,SAAW,EAAW,OAAO,WAAW,CAAG,EAAI,IAAM,EAAI,IACnE,CACA,IAAM,EAAO,i